func Or(predicates ...predicate.MindMapNode) predicate.MindMapNode {
	return predicate.MindMapNode(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.MindMapNode) predicate.MindMapNode {
	return predicate.MindMapNode(sql.NotPredicates(p))
}
